package dev.alan.mineworld;

import static org.junit.jupiter.api.Assertions.*;

import dev.alan.mineworld.city.CityLayout;
import java.util.List;
import java.util.Map;
import java.util.Random;
import org.junit.jupiter.api.Test;

class CityLayoutTest {
    /** Template footprints (x, z) as generated by scripts/gen_mineworld_data.py. */
    private static final Map<String, int[]> SIZE = Map.of("plaza", new int[]{18, 18}, "inn", new int[]{36, 16});

    private static int[] size(String template) { return SIZE.getOrDefault(template, new int[]{16, 16}); }

    @Test void buildingsFitInsideTheWallWithoutOverlapping() {
        for (long seed = 0; seed < 20; seed++) {
            List<CityLayout.Building> buildings = CityLayout.buildings(new Random(seed));
            assertEquals(16, buildings.size(), "plaza, inn, guard post and 13 plots");
            for (int i = 0; i < buildings.size(); i++) {
                var a = buildings.get(i);
                int[] sa = size(a.template());
                assertTrue(a.x() > -CityLayout.WALL_INNER && a.x() + sa[0] - 1 < CityLayout.WALL_INNER, a.toString());
                assertTrue(a.z() > -CityLayout.WALL_INNER && a.z() + sa[1] - 1 < CityLayout.WALL_INNER, a.toString());
                for (int j = i + 1; j < buildings.size(); j++) {
                    var b = buildings.get(j);
                    int[] sb = size(b.template());
                    boolean apart = a.x() + sa[0] <= b.x() || b.x() + sb[0] <= a.x() || a.z() + sa[1] <= b.z() || b.z() + sb[1] <= a.z();
                    assertTrue(apart, a + " overlaps " + b);
                }
            }
        }
    }

    @Test void buildingsLeaveTheMainStreetsFree() {
        for (var b : CityLayout.buildings(new Random(1))) {
            if (b.template().equals("plaza")) continue;
            int[] s = size(b.template());
            for (int x = b.x(); x < b.x() + s[0]; x++) {
                for (int z = b.z(); z < b.z() + s[1]; z++) assertFalse(CityLayout.isStreet(x, z), b + " covers the street at " + x + "," + z);
            }
        }
    }

    @Test void domeIsHighInTheMiddleAndAboveTheWall() {
        assertEquals(CityLayout.DOME_HEIGHT, CityLayout.ceiling(0, 0));
        for (int d = -CityLayout.WALL_OUTER; d <= CityLayout.WALL_OUTER; d++) {
            assertTrue(CityLayout.ceiling(d, CityLayout.WALL_OUTER) > CityLayout.WALL_HEIGHT + 1);
            assertTrue(CityLayout.ceiling(CityLayout.WALL_OUTER, CityLayout.WALL_OUTER) >= CityLayout.EDGE_HEIGHT);
        }
    }

    @Test void guardsStandOnTheWallOrInsideIt() {
        for (var g : CityLayout.guards()) {
            assertTrue(CityLayout.inside(g.x(), g.z()), g.toString());
            if (g.y() > 1) assertTrue(CityLayout.isWall(g.x(), g.z()), "wall guard on the wall: " + g);
        }
    }
}
